const input = document.querySelector("#name");
const add = document.querySelector("#add");
const list = document.querySelector("#list");
add.addEventListener("click", () => {
  if (input.value === "") {
    return;
  }
  const li = document.createElement("li");
  li.textContent = input.value;
  list.append(li);
  input.value = "";
});

